import com.google.firebase.firestore.FirebaseFirestore

/**
 * Screen presenting notification messages sent to the current user.
 *
 * @param navController Navigation controller for routing back to previous screen.
 */
@Composable
fun NotificationScreen(
    navController: NavController
) {
    val context = LocalContext.current
    val deviceId = remember(context) { DeviceIdentity.getDeviceId(context) }

    var notifications by remember { mutableStateOf<List<NotificationItem>>(emptyList()) }
    var isLoading by remember { mutableStateOf(true) }

    val buttonColor = Color(0xFF283618)
    val cardBg = Color(0xFFFEFAE0)

    DisposableEffect(deviceId) {
        val listener = FirebaseFirestore.getInstance()
            .collection("notifications")
            .whereEqualTo("userId", deviceId)
            .addSnapshotListener { snapshot, error ->
                if (error != null) {
                    isLoading = false
                    return@addSnapshotListener
                }
                val items = snapshot?.documents?.mapNotNull { doc ->
                    doc.toObject(NotificationItem::class.java)
                }?.sortedByDescending { it.timestamp } ?: emptyList()

                notifications = items
                isLoading = false
            }

        onDispose { listener.remove() }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .statusBarsPadding()
            .padding(16.dp)
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.Absolute.Left
        ) {
            Button(
                onClick = { navController.popBackStack() },
                shape = RectangleShape,
                modifier = Modifier.testTag("toBackButton"),
                colors = ButtonDefaults.buttonColors(containerColor = buttonColor, contentColor = Color.White)
            ) {
                Text("< Back")
            }
        }

        Spacer(modifier = Modifier.height(16.dp))
        Text("Notifications", fontSize = 24.sp, style = MaterialTheme.typography.headlineSmall)
        Spacer(modifier = Modifier.height(16.dp))

        when {
            isLoading -> {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    CircularProgressIndicator()
                }
            }

            notifications.isEmpty() -> {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Text(
                        "You have no notifications.",
                        fontSize = 16.sp,
                        modifier = Modifier.testTag("emptyNotifications")
                    )
                }
            }

            else -> {
                LazyColumn(
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f)
                        .testTag("notificationList")
                ) {
                    items(notifications, key = { it.notificationId }) { notification ->
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 6.dp)
                                .then(
                                    if (notification.type == "LOTTERY_WIN" && notification.waitlistId.isNotBlank()) {
                                        Modifier.clickable {
                                            navController.navigate("booking/${notification.waitlistId}")
                                        }
                                    } else if (notification.type == "RESERVATION" || notification.type == "RESERVATION_CANCELLED" || notification.type == "RESERVATION_REJECTED") {
                                        Modifier.clickable {
                                            navController.navigate("reservation")
                                        }
                                    } else if (notification.type == "LOTTERY_JOINED") {
                                        Modifier.clickable {
                                            if (notification.campsiteId.isNotBlank()) {
                                                navController.navigate("campsiteInfo/${notification.campsiteId}")
                                            } else if (notification.waitlistId.isNotBlank()) {
                                                navController.navigate("booking/${notification.waitlistId}")
                                            }
                                        }
                                    } else Modifier
                                ),
                            colors = CardDefaults.cardColors(
                                containerColor = buttonColor,
                                contentColor = cardBg
                            )
                        ) {
                            Column(modifier = Modifier.padding(16.dp)) {
                                Text(
                                    text = notification.title,
                                    fontSize = 20.sp,
                                    style = MaterialTheme.typography.titleMedium,
                                    color = cardBg
                                )
                                Spacer(modifier = Modifier.height(4.dp))
                                Text(
                                    text = notification.message,
                                    fontSize = 15.sp,
                                    color = cardBg
                                )
                                Spacer(modifier = Modifier.height(8.dp))
                                Text(
                                    text = dateLongUIFormat(notification.timestamp),
                                    fontSize = 12.sp,
                                    color = cardBg.copy(alpha = 0.8f)
                                )

                                if (notification.type == "LOTTERY_WIN" && notification.waitlistId.isNotBlank()) {
                                    Spacer(modifier = Modifier.height(8.dp))
                                    Button(
                                        onClick = {
                                            navController.navigate("booking/${notification.waitlistId}")
                                        },
                                        shape = RectangleShape,
                                        colors = ButtonDefaults.buttonColors(
                                            containerColor = cardBg,
                                            contentColor = buttonColor
                                        )
                                    ) {
                                        Text("Reserve Now")
                                    }
                                } else if (notification.type == "RESERVATION") {
                                    Spacer(modifier = Modifier.height(8.dp))
                                    Button(
                                        onClick = {
                                            navController.navigate("reservation")
                                        },
                                        shape = RectangleShape,
                                        colors = ButtonDefaults.buttonColors(
                                            containerColor = cardBg,
                                            contentColor = buttonColor
                                        )
                                    ) {
                                        Text("View Reservation")
                                    }
                                } else if (notification.type == "LOTTERY_JOINED") {
                                    Spacer(modifier = Modifier.height(8.dp))
                                    Button(
                                        onClick = {
                                            if (notification.campsiteId.isNotBlank()) {
                                                navController.navigate("campsiteInfo/${notification.campsiteId}")
                                            } else if (notification.waitlistId.isNotBlank()) {
                                                navController.navigate("booking/${notification.waitlistId}")
                                            }
                                        },
                                        shape = RectangleShape,
                                        colors = ButtonDefaults.buttonColors(
                                            containerColor = cardBg,
                                            contentColor = buttonColor
                                        )
                                    ) {
                                        Text("View Lottery Details")
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

